import{_ as d,o as e,c as a,ah as o}from"./chunks/framework.Yx0DUrwu.js";const b=JSON.parse('{"title":"淋巴细胞发育与活化","description":"","frontmatter":{},"headers":[],"relativePath":"biology/lymphocyte-development-activation.md","filePath":"biology/lymphocyte-development-activation.md","lastUpdated":1787830595000}'),c={name:"biology/lymphocyte-development-activation.md"};function r(h,t,l,n,i,s){return e(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="淋巴细胞发育与活化" tabindex="-1">淋巴细胞发育与活化 <a class="header-anchor" href="#淋巴细胞发育与活化" aria-label="Permalink to &quot;淋巴细胞发育与活化&quot;">​</a></h1><p>适应性免疫的能力来自一个看似矛盾的过程：先通过 V(D)J 重排制造大量随机受体，再通过发育选择和外周调控清除危险的自身反应性克隆。这个过程决定了 T/B 细胞受体库的广度，也决定了免疫耐受的底线 [1]。</p><h2 id="受体库如何产生" tabindex="-1">受体库如何产生 <a class="header-anchor" href="#受体库如何产生" aria-label="Permalink to &quot;受体库如何产生&quot;">​</a></h2><div class="flow-strip"><span>造血干细胞</span><span>淋巴祖细胞</span><span>V(D)J 重排</span><span>受体表达测试</span><span>阳性选择</span><span>阴性选择</span><span>外周成熟</span><span>抗原激活</span></div><table tabindex="0"><thead><tr><th>机制</th><th>发生对象</th><th>作用</th><th>分析提示</th></tr></thead><tbody><tr><td>V(D)J 重排</td><td>BCR 重链/轻链，TCR alpha/beta/gamma/delta 链</td><td>产生受体多样性。</td><td>VDJ-seq 可连接克隆型与转录状态。</td></tr><tr><td>连接多样性</td><td>重排连接处核苷酸增减</td><td>主要扩展 CDR3 多样性。</td><td>CDR3 是克隆型分析核心区域。</td></tr><tr><td>等位基因排斥</td><td>B 细胞和 T 细胞</td><td>让单个细胞主要表达一个特异性受体。</td><td>双重受体或环境 RNA 污染需要谨慎判断。</td></tr><tr><td>类别转换重组</td><td>活化 B 细胞</td><td>改变抗体同种型，不改变抗原特异性。</td><td><code>IGHM</code>, <code>IGHD</code>, <code>IGHG</code>, <code>IGHA</code>, <code>AICDA</code>。</td></tr></tbody></table><h2 id="b-细胞发育" tabindex="-1">B 细胞发育 <a class="header-anchor" href="#b-细胞发育" aria-label="Permalink to &quot;B 细胞发育&quot;">​</a></h2><p>B 细胞在骨髓中完成早期发育：重链重排、pre-BCR 检查、轻链重排、自身反应性检查，然后进入外周继续成熟。单细胞中常见状态包括未成熟 B 细胞、初始 B 细胞、记忆 B 细胞、生发中心 B 细胞、浆母细胞和浆细胞。</p><table tabindex="0"><thead><tr><th>状态</th><th>常见标志基因</th><th>功能解释</th></tr></thead><tbody><tr><td>初始 B 细胞</td><td><code>MS4A1</code>, <code>CD79A</code>, <code>CD79B</code>, <code>IGHD</code>, <code>IGHM</code></td><td>未充分经历抗原驱动分化。</td></tr><tr><td>生发中心 B 细胞</td><td><code>BCL6</code>, <code>AICDA</code>, <code>MKI67</code></td><td>体细胞高频突变、选择和亲和力成熟。</td></tr><tr><td>记忆 B 细胞</td><td><code>CD27</code>, 已转换的 <code>IGHG</code>/<code>IGHA</code></td><td>再次应答更快，常有类别转换。</td></tr><tr><td>浆细胞</td><td><code>MZB1</code>, <code>XBP1</code>, <code>JCHAIN</code>, <code>SDC1</code></td><td>大量分泌抗体。</td></tr></tbody></table><h2 id="t-细胞发育" tabindex="-1">T 细胞发育 <a class="header-anchor" href="#t-细胞发育" aria-label="Permalink to &quot;T 细胞发育&quot;">​</a></h2><p>T 细胞起源于骨髓，但关键发育发生在胸腺。Notch 信号推动 T 细胞谱系定向；pre-TCR 检查 beta 链；阳性选择保留能识别自身 MHC 的细胞；阴性选择清除高亲和识别自身抗原的细胞。部分自身反应性细胞会进入 Treg 或固有样 T 细胞命运。</p><div class="doc-callout important"><strong>选择不是越强越好</strong><p>TCR 信号太弱，细胞无法通过阳性选择；太强，可能触发阴性选择或 Treg 命运。免疫系统是在识别能力和自身耐受之间找平衡。</p></div><h2 id="tcr-bcr-信号和共刺激" tabindex="-1">TCR/BCR 信号和共刺激 <a class="header-anchor" href="#tcr-bcr-信号和共刺激" aria-label="Permalink to &quot;TCR/BCR 信号和共刺激&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模块</th><th>关键分子</th><th>作用</th><th>单细胞解释</th></tr></thead><tbody><tr><td>TCR 信号</td><td><code>CD3D/E/G</code>, <code>LCK</code>, <code>ZAP70</code>, <code>LAT</code></td><td>抗原识别后启动胞内级联。</td><td><code>FOS</code>, <code>JUN</code>, <code>NR4A1</code>, <code>IL2RA</code> 可提示近期激活。</td></tr><tr><td>BCR 信号</td><td><code>CD79A/B</code>, <code>SYK</code>, <code>BLNK</code></td><td>抗原结合后促进 B 细胞活化。</td><td>与抗原摄取、Tfh 辅助、类别转换联合解释。</td></tr><tr><td>共刺激</td><td>CD28、CD40、ICOS</td><td>提供完全激活信号。</td><td>T 细胞启动、T-B 相互作用、Tfh 应答。</td></tr><tr><td>共抑制</td><td>CTLA-4、PD-1、磷酸酶招募</td><td>限制过强免疫反应。</td><td>耗竭、Treg 功能、免疫检查点治疗响应。</td></tr></tbody></table><h2 id="自检问题" tabindex="-1">自检问题 <a class="header-anchor" href="#自检问题" aria-label="Permalink to &quot;自检问题&quot;">​</a></h2><ol><li>为什么 V(D)J 重排必须配套中枢和外周耐受？</li><li>阳性选择和阴性选择分别筛选什么？</li><li>CD28、CTLA-4 和 PD-1 在免疫调控中有什么差异？</li><li>单细胞 TCR 克隆型扩增一定代表抗原特异性吗？</li></ol><h2 id="参考资料" tabindex="-1">参考资料 <a class="header-anchor" href="#参考资料" aria-label="Permalink to &quot;参考资料&quot;">​</a></h2><p>[1] Murphy, K. &amp; Weaver, C. <em>Janeway&#39;s Immunobiology</em>. 9th ed. Garland Science (2017). 中文版：《詹韦免疫生物学：原书第九版》，科学出版社，2022。</p>',17)])])}const C=d(c,[["render",r]]);export{b as __pageData,C as default};
